window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["claude"]={html:"<div class=\"own-claude\">\n  <header class=\"nav\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Northwind home\">\n      <span class=\"spike\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M2 12h20M5 5l14 14M19 5L5 19\"/></svg></span>\n      <span class=\"brand-word\">Northwind</span>\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#product\">Product</a>\n      <a href=\"#solutions\">Solutions</a>\n      <a href=\"#models\">Models</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#research\">Research</a>\n    </nav>\n    <div class=\"nav-right\">\n      <a class=\"nav-signin\" href=\"#\">Sign in</a>\n      <a class=\"btn btn-primary\" href=\"#\">Try Northwind</a>\n    </div>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"hero-copy\">\n        <p class=\"caption-upper\">Operations analytics</p>\n        <h1 id=\"heroH\">Meet your thinking partner for operations</h1>\n        <p class=\"lead\">Northwind reads your regional telemetry, drafts the review, and explains every number — a warm, considered interface for serious operations work.</p>\n        <div class=\"hero-actions\">\n          <a class=\"btn btn-primary\" href=\"#\">Try Northwind free</a>\n          <a class=\"link-inline\" href=\"#product\">See how it works &rarr;</a>\n        </div>\n      </div>\n      <div class=\"hero-art\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 420 320\" class=\"art-svg\">\n          <rect x=\"30\" y=\"30\" width=\"360\" height=\"260\" rx=\"16\" fill=\"#181715\"/>\n          <rect x=\"30\" y=\"30\" width=\"360\" height=\"40\" rx=\"16\" fill=\"#252320\"/>\n          <circle cx=\"54\" cy=\"50\" r=\"5\" fill=\"#cc785c\"/><circle cx=\"74\" cy=\"50\" r=\"5\" fill=\"#e8a55a\"/><circle cx=\"94\" cy=\"50\" r=\"5\" fill=\"#5db8a6\"/>\n          <rect x=\"56\" y=\"98\" width=\"130\" height=\"10\" rx=\"5\" fill=\"#3d3d3a\"/>\n          <rect x=\"56\" y=\"120\" width=\"200\" height=\"10\" rx=\"5\" fill=\"#2c2b28\"/>\n          <rect x=\"56\" y=\"142\" width=\"170\" height=\"10\" rx=\"5\" fill=\"#2c2b28\"/>\n          <rect x=\"56\" y=\"176\" width=\"308\" height=\"44\" rx=\"10\" fill=\"#1f1e1b\" stroke=\"#cc785c\" stroke-width=\"1.5\"/>\n          <rect x=\"72\" y=\"192\" width=\"180\" height=\"12\" rx=\"6\" fill=\"#5db8a6\"/>\n          <rect x=\"56\" y=\"236\" width=\"90\" height=\"30\" rx=\"15\" fill=\"#cc785c\"/>\n        </svg>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"features\" id=\"product\" aria-labelledby=\"featH\">\n    <div class=\"wrap\">\n      <div class=\"head-block\">\n        <p class=\"caption-upper\">What's inside</p>\n        <h2 id=\"featH\" class=\"display-lg\">A calmer way to work with your operations data</h2>\n      </div>\n      <div class=\"feature-grid\">\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 19V5M4 19h16M8 15l3-5 3 3 4-7\"/></svg></span>\n          <h3>Ask in plain language</h3>\n          <p>Query every region in a sentence and get an answer with the reasoning attached.</p>\n        </article>\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 9h18M7 13h6\"/></svg></span>\n          <h3>Draft the review</h3>\n          <p>Northwind assembles the weekly operations review from live throughput and cost.</p>\n        </article>\n        <article class=\"feature-card\">\n          <span class=\"ficon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 3v18M3 12h18\"/><circle cx=\"12\" cy=\"12\" r=\"9\"/></svg></span>\n          <h3>Explain the numbers</h3>\n          <p>Every figure links back to its source rows, so your team can trust the total.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"codeband\" id=\"research\" aria-labelledby=\"codeH\">\n    <div class=\"wrap code-grid\">\n      <div class=\"code-copy\">\n        <p class=\"caption-upper\">Developer-first</p>\n        <h2 id=\"codeH\" class=\"display-lg\">Show the query, not a diagram of it</h2>\n        <p class=\"lead\">Northwind embeds a real operations console — SQL, terminal and all. Paste a query, get a dashboard back.</p>\n        <a class=\"link-inline\" href=\"#\">Read the API docs &rarr;</a>\n      </div>\n      <div class=\"code-window\" aria-hidden=\"true\">\n        <div class=\"code-bar\"><span class=\"cdot r\"></span><span class=\"cdot y\"></span><span class=\"cdot g\"></span><span class=\"code-file\">weekly_ops.sql</span></div>\n        <pre class=\"code-body\"><span class=\"ln\">1</span><span class=\"kw\">SELECT</span> region, <span class=\"fn\">sum</span>(events) <span class=\"kw\">AS</span> throughput\n<span class=\"ln\">2</span><span class=\"kw\">FROM</span> ops.telemetry\n<span class=\"ln\">3</span><span class=\"kw\">WHERE</span> ts &gt;= <span class=\"st\">'2026-10-01'</span>\n<span class=\"ln\">4</span><span class=\"kw\">GROUP BY</span> region\n<span class=\"ln\">5</span><span class=\"kw\">ORDER BY</span> throughput <span class=\"kw\">DESC</span>;</pre>\n        <div class=\"code-status\"><span class=\"ok-dot\"></span>Query finished · 6 rows · 0.42s</div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"models\" id=\"models\" aria-labelledby=\"modelsH\">\n    <div class=\"wrap\">\n      <div class=\"head-block\">\n        <p class=\"caption-upper\">Which problem are you up against?</p>\n        <h2 id=\"modelsH\" class=\"display-lg\">Three models, one console</h2>\n      </div>\n      <div class=\"model-grid\">\n        <article class=\"model-card\">\n          <h3>Opus</h3>\n          <p class=\"muted\">The deepest reasoning for the hardest operations questions and cross-region reconciliation.</p>\n          <a class=\"link-inline\" href=\"#\">Learn more &rarr;</a>\n        </article>\n        <article class=\"model-card\">\n          <h3>Sonnet</h3>\n          <p class=\"muted\">Balanced speed and depth for daily dashboards and scheduled reviews.</p>\n          <a class=\"link-inline\" href=\"#\">Learn more &rarr;</a>\n        </article>\n        <article class=\"model-card\">\n          <h3>Haiku</h3>\n          <p class=\"muted\">Fast, cheap answers for high-volume alerts and metric lookups.</p>\n          <a class=\"link-inline\" href=\"#\">Learn more &rarr;</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"callout\">\n    <div class=\"wrap callout-inner\">\n      <h2 class=\"display-sm\">Bring Northwind to your operations team</h2>\n      <p>Start free, no setup call. Coral card, calmer reviews.</p>\n      <a class=\"btn btn-on-coral\" href=\"#\">Try Northwind free</a>\n    </div>\n  </section>\n\n  <section class=\"pricing\" id=\"pricing\" aria-labelledby=\"priceH\">\n    <div class=\"wrap\">\n      <div class=\"head-block center\">\n        <h2 id=\"priceH\" class=\"display-lg\">Plans that scale with your grid</h2>\n      </div>\n      <div class=\"pricing-grid\">\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Free</h3>\n          <p class=\"tier-price\">$0</p>\n          <ul class=\"check-list\"><li>1 region</li><li>7-day retention</li><li>Community support</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"tier tier-featured\">\n          <span class=\"badge-coral\">Featured</span>\n          <h3 class=\"tier-name\">Pro</h3>\n          <p class=\"tier-price\">$49</p>\n          <ul class=\"check-list\"><li>18 regions</li><li>13-month retention</li><li>Alert routing</li></ul>\n          <a class=\"btn btn-on-dark\" href=\"#\">Start free</a>\n        </article>\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Team</h3>\n          <p class=\"tier-price\">$99</p>\n          <ul class=\"check-list\"><li>41 regions</li><li>36-month retention</li><li>24/7 support</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"footer-cta\">\n    <div class=\"wrap footer-cta-inner\">\n      <h2 class=\"display-sm\">Start your next operations review with Northwind</h2>\n      <a class=\"btn btn-primary btn-lg\" href=\"#\">Try Northwind free</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"wrap foot-grid\">\n      <div class=\"foot-brand\">\n        <span class=\"spike\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M12 2v20M2 12h20M5 5l14 14M19 5L5 19\"/></svg></span>\n        <span class=\"foot-word\">Northwind</span>\n      </div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Product</p><a href=\"#\">Dashboards</a><a href=\"#\">Models</a><a href=\"#\">API</a><a href=\"#\">Pricing</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Resources</p><a href=\"#\">Docs</a><a href=\"#\">Status</a><a href=\"#\">Security</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Legal</p><a href=\"#\">Privacy</a><a href=\"#\">Terms</a></div>\n    </div>\n    <div class=\"wrap foot-bottom\">\n      <p>Northwind is a fictional product. Sample data — showcase only.</p>\n      <span>© 2026</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Claude design language ════════════════\n   Scoped under .own-claude. Tokens from design-md/claude/DESIGN.md. Warm cream\n   canvas, coral primary CTA (scarce on buttons, generous on the full-bleed\n   callout), Copernicus slab-serif display (substituted by a serif stack) vs\n   StyreneB/Inter humanist body, and dark navy product surfaces. */\n\n.own-claude {\n  --canvas: #faf9f5;\n  --surface-soft: #f5f0e8;\n  --surface-card: #efe9de;\n  --surface-cream-strong: #e8e0d2;\n  --surface-dark: #181715;\n  --surface-dark-elevated: #252320;\n  --surface-dark-soft: #1f1e1b;\n  --ink: #141413;\n  --body: #3d3d3a;\n  --body-strong: #252523;\n  --muted: #6c6a64;\n  --muted-soft: #8e8b82;\n  --hairline: #e6dfd8;\n  --hairline-soft: #ebe6df;\n  --primary: #cc785c;\n  --primary-active: #a9583e;\n  --on-primary: #ffffff;\n  --on-dark: #faf9f5;\n  --on-dark-soft: #a09d96;\n  --accent-teal: #5db8a6;\n  --accent-amber: #e8a55a;\n\n  --display: \"Copernicus\", \"Tiempos Headline\", \"Cormorant Garamond\", \"EB Garamond\", Garamond, \"Times New Roman\", serif;\n  --body-font: \"StyreneB\", \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n\n  --gut: clamp(20px, 4.4cqi, 32px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--body-font);\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.55;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-claude *,\n.own-claude *::before,\n.own-claude *::after { box-sizing: border-box; }\n.own-claude :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: 4px; }\n.own-claude a { color: inherit; text-decoration: none; }\n.own-claude .wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--gut); }\n.own-claude .center { text-align: center; }\n.own-claude .muted { color: var(--muted); }\n.own-claude .lead { color: var(--body); font-size: 17px; line-height: 1.55; }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-claude .display-lg {\n  font-family: var(--display); font-weight: 400;\n  font-size: clamp(32px, 4.4cqi, 48px); line-height: 1.1; letter-spacing: -.02em; margin: 0;\n}\n.own-claude .display-sm {\n  font-family: var(--display); font-weight: 400;\n  font-size: clamp(24px, 2.6cqi, 28px); line-height: 1.2; letter-spacing: -.01em; margin: 0;\n}\n.own-claude .caption-upper {\n  font-family: var(--body-font); font-weight: 500; font-size: 12px; letter-spacing: 1.5px;\n  text-transform: uppercase; color: var(--muted); margin: 0 0 14px;\n}\n.own-claude .head-block { max-width: 720px; margin-bottom: 44px; }\n.own-claude .head-block.center { margin-left: auto; margin-right: auto; text-align: center; }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-claude .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 0 20px; border-radius: 8px;\n  font-family: var(--body-font); font-weight: 500; font-size: 14px;\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: background-color .15s ease, color .15s ease, border-color .15s ease;\n}\n.own-claude .btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-claude .btn-primary:hover { background: var(--primary-active); }\n.own-claude .btn-secondary { background: transparent; color: var(--ink); border-color: var(--hairline); }\n.own-claude .btn-secondary:hover { border-color: var(--muted-soft); }\n.own-claude .btn-on-coral { background: var(--canvas); color: var(--ink); }\n.own-claude .btn-on-dark { background: var(--surface-dark-elevated); color: var(--on-dark); }\n.own-claude .btn-lg { height: 44px; padding: 0 26px; font-size: 15px; }\n.own-claude .link-inline { color: var(--primary); font-weight: 500; font-size: 14px; }\n.own-claude .link-inline:hover { text-decoration: underline; }\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-claude .nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 30px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(250,249,245,.9); border-bottom: 1px solid var(--hairline-soft);\n  backdrop-filter: blur(8px);\n}\n.own-claude .brand { display: inline-flex; align-items: center; gap: 10px; }\n.own-claude .spike { width: 22px; height: 22px; display: inline-block; }\n.own-claude .spike svg { width: 100%; height: 100%; fill: none; stroke: var(--ink); stroke-width: 1.4; stroke-linecap: round; }\n.own-claude .brand-word { font-family: var(--body-font); font-weight: 500; font-size: 18px; letter-spacing: -.01em; }\n.own-claude .nav-links { display: flex; align-items: center; gap: 24px; }\n.own-claude .nav-links a { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-claude .nav-links a:hover { color: var(--ink); }\n.own-claude .nav-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-claude .nav-signin { font-size: 14px; font-weight: 500; }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-claude .hero { padding: var(--section) 0; }\n.own-claude .hero-grid { display: grid; grid-template-columns: 6fr 6fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-claude .hero h1 {\n  font-family: var(--display); font-weight: 400;\n  font-size: clamp(38px, 5.4cqi, 64px); line-height: 1.05; letter-spacing: -.025em; margin: 0 0 20px;\n}\n.own-claude .hero-actions { display: flex; align-items: center; gap: 24px; flex-wrap: wrap; margin-top: 28px; }\n.own-claude .hero-art { background: var(--surface-card); border-radius: 16px; overflow: hidden; }\n.own-claude .art-svg { display: block; width: 100%; height: auto; }\n\n/* ── features ────────────────────────────────────────────────────────── */\n.own-claude .features { padding: var(--section) 0; background: var(--surface-soft); }\n.own-claude .feature-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-claude .feature-card { background: var(--surface-card); border-radius: 12px; padding: 32px; }\n.own-claude .ficon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--canvas); margin-bottom: 20px; }\n.own-claude .ficon svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.own-claude .feature-card h3 { font-family: var(--display); font-weight: 400; font-size: 22px; letter-spacing: -.01em; margin: 0 0 10px; }\n.own-claude .feature-card p { color: var(--body); margin: 0; }\n\n/* ── code band ───────────────────────────────────────────────────────── */\n.own-claude .codeband { padding: var(--section) 0; }\n.own-claude .code-grid { display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-claude .code-copy .display-lg { max-width: 12ch; margin-bottom: 16px; }\n.own-claude .code-copy .lead { margin-bottom: 20px; }\n.own-claude .code-window { background: var(--surface-dark); border-radius: 12px; padding: 24px; overflow: hidden; }\n.own-claude .code-bar { display: flex; align-items: center; gap: 7px; margin-bottom: 18px; }\n.own-claude .cdot { width: 11px; height: 11px; border-radius: 9999px; }\n.own-claude .cdot.r { background: #c64545; } .own-claude .cdot.y { background: var(--accent-amber); } .own-claude .cdot.g { background: #5db872; }\n.own-claude .code-file { margin-left: 12px; font-family: var(--mono); font-size: 12px; color: var(--on-dark-soft); }\n.own-claude .code-body { margin: 0; font-family: var(--mono); font-size: 14px; line-height: 1.6; color: var(--on-dark); white-space: pre; overflow-x: auto; }\n.own-claude .code-body .ln { display: inline-block; width: 24px; color: var(--muted-soft); user-select: none; }\n.own-claude .code-body .kw { color: #e8a55a; } .own-claude .code-body .fn { color: var(--accent-teal); } .own-claude .code-body .st { color: #a9c6a0; }\n.own-claude .code-status { display: flex; align-items: center; gap: 8px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--surface-dark-elevated); font-family: var(--mono); font-size: 12px; color: var(--on-dark-soft); }\n.own-claude .ok-dot { width: 8px; height: 8px; border-radius: 9999px; background: #5db872; }\n\n/* ── models ──────────────────────────────────────────────────────────── */\n.own-claude .models { padding: var(--section) 0; }\n.own-claude .model-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-claude .model-card { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; }\n.own-claude .model-card h3 { font-family: var(--display); font-weight: 400; font-size: 28px; letter-spacing: -.01em; margin: 0 0 12px; }\n.own-claude .model-card p { color: var(--body); margin: 0 0 20px; }\n.own-claude .model-card .link-inline { margin-top: auto; }\n\n/* ── coral callout ───────────────────────────────────────────────────── */\n.own-claude .callout { padding: 0 var(--gut) var(--section); }\n.own-claude .callout-inner { max-width: 1200px; margin: 0 auto; background: var(--primary); color: var(--on-primary); border-radius: 12px; padding: clamp(40px, 5.5cqi, 64px); text-align: center; display: grid; justify-items: center; gap: 14px; }\n.own-claude .callout-inner p { margin: 0; color: rgba(255,255,255,.9); }\n.own-claude .callout-inner .btn { margin-top: 8px; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-claude .pricing { padding: var(--section) 0; background: var(--surface-soft); }\n.own-claude .pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-claude .tier { background: var(--canvas); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; }\n.own-claude .tier-featured { background: var(--surface-dark); border-color: var(--surface-dark); color: var(--on-dark); }\n.own-claude .badge-coral { align-self: flex-start; background: var(--primary); color: var(--on-primary); font-size: 12px; font-weight: 500; letter-spacing: 1.5px; text-transform: uppercase; padding: 4px 12px; border-radius: 9999px; margin-bottom: 16px; }\n.own-claude .tier-name { font-family: var(--body-font); font-weight: 500; font-size: 22px; letter-spacing: -.01em; margin: 0 0 12px; }\n.own-claude .tier-price { font-family: var(--display); font-weight: 400; font-size: 28px; letter-spacing: -.01em; margin: 0 0 20px; }\n.own-claude .check-list { list-style: none; margin: 0 0 24px; padding: 0; display: grid; gap: 12px; }\n.own-claude .check-list li { position: relative; padding-left: 28px; color: var(--body); }\n.own-claude .check-list li::before { content: \"\"; position: absolute; left: 0; top: 4px; width: 16px; height: 9px; border-left: 2px solid var(--primary); border-bottom: 2px solid var(--primary); transform: rotate(-45deg); }\n.own-claude .tier-featured .check-list li { color: var(--on-dark-soft); }\n.own-claude .tier .btn { margin-top: auto; }\n\n/* ── footer cta ──────────────────────────────────────────────────────── */\n.own-claude .footer-cta { padding: clamp(48px, 6cqi, 72px) 0; }\n.own-claude .footer-cta-inner { display: grid; justify-items: center; gap: 20px; text-align: center; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-claude .foot { background: var(--surface-dark); color: var(--on-dark-soft); padding: clamp(48px, 6cqi, 64px) 0 28px; }\n.own-claude .foot-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 24px; padding-bottom: 40px; }\n.own-claude .foot-brand { display: flex; align-items: center; gap: 10px; }\n.own-claude .foot-brand .spike svg { stroke: var(--on-dark); }\n.own-claude .foot-word { font-family: var(--body-font); font-weight: 500; font-size: 18px; color: var(--on-dark); }\n.own-claude .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-claude .foot-h { font-size: 13px; font-weight: 500; color: var(--on-dark); margin: 0 0 4px; }\n.own-claude .foot-col a { font-size: 14px; color: var(--on-dark-soft); }\n.own-claude .foot-col a:hover { color: var(--on-dark); }\n.own-claude .foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--surface-dark-elevated); font-size: 13px; }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-claude .hero-grid, .own-claude .code-grid { grid-template-columns: 1fr; }\n  .own-claude .hero-art { order: -1; }\n  .own-claude .feature-grid, .own-claude .model-grid, .own-claude .pricing-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-claude .foot-grid { grid-template-columns: 1.4fr repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-claude .nav-links, .own-claude .nav-signin { display: none; }\n  .own-claude .feature-grid, .own-claude .model-grid, .own-claude .pricing-grid { grid-template-columns: 1fr; }\n  .own-claude .foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-claude .foot-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-claude *, .own-claude *::before, .own-claude *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
